/** listobjects — 列出目录下节点名（参数无关：value=可选路径） */
treenode replyNode = param(1);
treenode parsedRequestNode = param(2);
treenode vn = node("GET/value", parsedRequestNode);
treenode parent = model();
if (vn && stringlen(gets(vn)) > 0) {
	parent = node(gets(vn), model());
	if (!objectexists(parent)) { setnodestr(replyNode, "<status>error</status><reason>path not found</reason>"); return replyNode; }
}
string list = "";
int count = 0;
for (int i = 1; i <= parent.subnodes.length; i++) {
	treenode sub = parent.subnodes[i];
	string nm = getnodename(sub);
	if (stringlen(nm) > 0) {
		if (count > 0) list += ",";
		list += nm;
		count++;
	}
}
setnodestr(replyNode, "<status>success</status><count>" + numtostring(count,0,0) + "</count><names>" + list + "</names>");
return replyNode;

/** getstats — 读对象累计统计（参数无关：value=对象名, action=字段名） */
treenode replyNode = param(1);
treenode parsedRequestNode = param(2);
treenode vn = node("GET/value", parsedRequestNode);
if (!vn) { setnodestr(replyNode, "<status>error</status><reason>missing value</reason>"); return replyNode; }
string objName = gets(vn);
treenode obj = node(objName, model());
if (!objectexists(obj)) { setnodestr(replyNode, "<status>error</status><reason>object not found: " + objName + "</reason>"); return replyNode; }
string field = "variable_nrreleased";
treenode an = node("GET/action", parsedRequestNode);
if (an && stringlen(gets(an)) > 0) field = gets(an);
treenode f = obj.find(field);
if (!objectexists(f)) { setnodestr(replyNode, "<status>error</status><reason>field not found: " + field + "</reason>"); return replyNode; }
string val = numtostring(getnodenum(f), 0, 4);
setnodestr(replyNode, "<status>success</status><object>" + objName + "</object><field>" + field + "</field><value>" + val + "</value>");
return replyNode;

/** renamenode — 节点/对象改名（参数无关：value=旧路径, name=新名） */
treenode replyNode = param(1);
treenode parsedRequestNode = param(2);
treenode vn = node("GET/value", parsedRequestNode);
treenode nn = node("GET/name", parsedRequestNode);
if (!vn || !nn) { setnodestr(replyNode, "<status>error</status><reason>missing value or name</reason>"); return replyNode; }
string oldPath = gets(vn);
string newName = gets(nn);
treenode target = node(oldPath, model());
if (!objectexists(target)) { setnodestr(replyNode, "<status>error</status><reason>node not found: " + oldPath + "</reason>"); return replyNode; }
setnodename(target, newName);
setnodestr(replyNode, "<status>success</status><old>" + oldPath + "</old><new>" + newName + "</new>");
return replyNode;

/** copyobject — 复制对象（参数无关：value=源对象名, name=新名） */
treenode replyNode = param(1);
treenode parsedRequestNode = param(2);
treenode vn = node("GET/value", parsedRequestNode);
treenode nn = node("GET/name", parsedRequestNode);
if (!vn || !nn) { setnodestr(replyNode, "<status>error</status><reason>missing value or name</reason>"); return replyNode; }
string srcName = gets(vn);
string newName = gets(nn);
treenode src = node(srcName, model());
if (!objectexists(src)) { setnodestr(replyNode, "<status>error</status><reason>object not found: " + srcName + "</reason>"); return replyNode; }
treenode copy = createcopy(src, model());
setnodename(copy, newName);
setnodestr(replyNode, "<status>success</status><object>" + newName + "</object>");
return replyNode;

/** setcode — 原地修改 handler 代码（参数无关：value=handler名, action=新代码） */
treenode replyNode = param(1);
treenode parsedRequestNode = param(2);
treenode vn = node("GET/value", parsedRequestNode);
treenode an = node("GET/action", parsedRequestNode);
if (!vn || !an) { setnodestr(replyNode, "<status>error</status><reason>missing value or action</reason>"); return replyNode; }
string hName = gets(vn);
string newCode = gets(an);
treenode handler = node("Tools/serverinterface/queryhandlers/" + hName, model());
if (!objectexists(handler)) { setnodestr(replyNode, "<status>error</status><reason>handler not found: " + hName + "</reason>"); return replyNode; }
setnodestr(handler, newCode);
switch_flexscript(handler, 1);
buildnodeflexscript(handler);
setnodestr(replyNode, "<status>success</status><handler>" + hName + "</handler>");
return replyNode;
